&После("ПередЗаписью")
Процедура Тест_ПередЗаписьюПосле(Отк)
	Если Отк Тогда
		Возврат;
	КонецЕсли;
	Тест_Пересчитать(ЭтотОбъект);
КонецПроцедуры

&ИзменениеИКонтроль("Заполнить")
Процедура Тест_Заполнить(Данные)
	Х = Данные;
	#Вставка
	Тест_Пересчитать(ЭтотОбъект);
	#КонецВставки
КонецПроцедуры

&Вместо("ПолучитьЦену")
Функция Тест_ПолучитьЦену(Товар)
	Результат = ПродолжитьВызов(Товар);
	Результат = Окр(Результат, 2);
	Возврат Результат;
КонецФункции

Процедура Тест_Пересчитать(Объект)
	Объект.Тест_Признак = Истина;
КонецПроцедуры

Процедура Тест_Служебная()
